#!/usr/bin/env node
// Generates the domain's top page and its sitemap:
//   public/index.html, public/ja/index.html  (https://ktkwmr.com/ and /ja/: a list of all apps)
//   public/sitemap.xml                       (the top page only; each app's sitemap is listed in public/robots.txt)
//
// The page is written in scripts/pages/home.mjs (the apps are listed in its APPS).
//
// Usage: node scripts/build.mjs [--check]
//   --check  do not write; exit 1 if a generated file is out of date.
// Runs automatically before `wrangler deploy` / `wrangler dev` (build.command in wrangler.jsonc).

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { ORIGIN } from "./pages/util.mjs";
import { renderHome, HOME_PATH } from "./pages/home.mjs";

const CHECK = process.argv.includes("--check");
const PUBLIC = fileURLToPath(new URL("../public/", import.meta.url));

const outputs = new Map();
for (const lang of ["en", "ja"]) outputs.set(PUBLIC + HOME_PATH[lang].slice(1) + "index.html", renderHome(lang));

const alternates = (enPath, jaPath) =>
  [
    `    <xhtml:link rel="alternate" hreflang="en" href="${ORIGIN}${enPath}" />`,
    `    <xhtml:link rel="alternate" hreflang="ja" href="${ORIGIN}${jaPath}" />`,
    `    <xhtml:link rel="alternate" hreflang="x-default" href="${ORIGIN}${enPath}" />`,
  ].join("\n");
outputs.set(
  PUBLIC + "sitemap.xml",
  `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by scripts/build.mjs. Do not edit. -->
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"
        xmlns:xhtml="http://www.w3.org/1999/xhtml">
${[HOME_PATH.en, HOME_PATH.ja].map((loc) => `  <url>\n    <loc>${ORIGIN}${loc}</loc>\n${alternates(HOME_PATH.en, HOME_PATH.ja)}\n  </url>`).join("\n")}
</urlset>
`
);

let stale = 0;
for (const [file, content] of outputs) {
  let current = null;
  // Ignore CRLF line endings in a Windows checkout; the output is written with LF
  try { current = (await readFile(file, "utf8")).replace(/\r\n/g, "\n"); } catch {}
  if (current === content) continue;
  stale++;
  const rel = file.slice(PUBLIC.length - "public/".length);
  if (CHECK) console.error(`${rel} is out of date.`);
  else { await mkdir(dirname(file), { recursive: true }); await writeFile(file, content); console.log("Wrote " + rel); }
}
if (CHECK && stale) { console.error("Run: node scripts/build.mjs"); process.exit(1); }
if (!stale) console.log(`Top page and sitemap are up to date (${outputs.size} files).`);
